"""The `LineageProvider` seam — pull a lineage graph from a catalog (ADR 0034, #762)."""

from __future__ import annotations

from dataclasses import dataclass
from enum import StrEnum
from typing import Protocol, runtime_checkable


class LineageNodeKind(StrEnum):
    """The kind of a pulled lineage node — the "downstream isn't always a table" seam."""

    DATASET = "dataset"
    JOB = "job"
    BI_REPORT = "bi_report"
    DASHBOARD = "dashboard"
    UNKNOWN = "unknown"

    @classmethod
    def coerce(cls, raw: str | None) -> LineageNodeKind:
        """Map a provider's raw node-type string to a kind, defaulting to ``UNKNOWN``."""
        if not isinstance(raw, str):
            return cls.UNKNOWN
        token = raw.strip().lower()
        for kind in cls:
            if kind.value == token:
                return kind
        return cls.UNKNOWN


@dataclass(frozen=True)
class LineageNode:
    """One node in a pulled lineage graph."""

    node_id: str
    kind: LineageNodeKind
    namespace: str | None = None
    name: str | None = None


@dataclass(frozen=True)
class LineageGraph:
    """A normalized, directed lineage graph: nodes keyed by ``node_id`` + upstream→
    downstream edges (both endpoints are ``node_id`` keys present in ``nodes``).
    """

    nodes: dict[str, LineageNode]
    edges: tuple[tuple[str, str], ...]

    @classmethod
    def empty(cls) -> LineageGraph:
        """The empty graph — a *successful* pull that found nothing."""
        return cls(nodes={}, edges=())


class LineageUnavailableError(RuntimeError):
    """The catalog could not be consulted (transport error, non-2xx, garbage body)."""


@runtime_checkable
class LineageProvider(Protocol):
    """Provider-agnostic catalog-pull interface — Marquez is the reference impl."""

    provider: str

    def list_datasets(self, *, namespace: str) -> list[str]:
        """Every dataset name the catalog holds in ``namespace``."""
        ...

    def get_lineage(self, *, namespace: str, name: str, depth: int) -> LineageGraph:
        """Pull the lineage graph around the dataset ``namespace``/``name`` out to
        ``depth`` hops, normalized to a :class:`LineageGraph`.
        """
        ...
"""Warehouse-native lineage — pull edges straight from the warehouse (#858, ADR 0034)."""

from __future__ import annotations

from collections.abc import Sequence
from dataclasses import dataclass, field
from datetime import datetime
from enum import StrEnum
from functools import cache
from typing import Protocol, runtime_checkable

from backend.app.services.asset_identity import AssetIdentity


class LineageTier(StrEnum):
    """Which source answered a warehouse lineage pull — surfaced so a degraded graph
    never reads as a confident one (#828).
    """

    # Snowflake
    SNOWFLAKE_GET_LINEAGE = "snowflake_get_lineage"  # SNOWFLAKE.CORE.GET_LINEAGE (Enterprise+)
    SNOWFLAKE_ACCESS_HISTORY = "snowflake_access_history"  # ACCOUNT_USAGE.ACCESS_HISTORY (Ent+)
    SNOWFLAKE_OBJECT_DEPENDENCIES = "snowflake_object_dependencies"  # view-level, all editions
    # Unity Catalog
    UNITY_CATALOG_SYSTEM_ACCESS = "unity_catalog_system_access"  # system.access.table_lineage
    NONE = "none"

    @property
    def is_column_level(self) -> bool:
        """True for tiers that carry column-level detail (used to label the graph)."""
        return self in {self.SNOWFLAKE_GET_LINEAGE, self.SNOWFLAKE_ACCESS_HISTORY}


# Defensive per-edge cap on persisted column pairs (#901/#908): real schemas are bounded, but a
# generated/exploded join must not balloon the edge's JSONB.
MAX_COLUMN_PAIRS_PER_EDGE = 500


@dataclass(frozen=True)
class LineageEdgePair:
    """One directed edge as two OpenLineage identities — the warehouse provider's
    output unit. Both endpoints are already in the engine's own case, so they join
    `assets` byte-for-byte with no fold (the whole point vs the catalog seam).
    """

    upstream: AssetIdentity
    downstream: AssetIdentity
    column_pairs: tuple[tuple[str, str], ...] = ()


@dataclass(frozen=True)
class WarehouseLineageResult:
    """A successful warehouse pull: the edges found, the tier that produced them, and a
    human note when the answer is degraded (edition-gated, missing grant) — never a
    silent empty (#828).
    """

    edges: tuple[LineageEdgePair, ...]
    tier: LineageTier
    degraded_reason: str | None = None
    freshness_lag: str | None = None
    # Tiers whose absence was detected during the preflight/ladder descent — carried so
    # the UI/log can say "GET_LINEAGE unavailable (edition), fell back to …".
    skipped_tiers: tuple[str, ...] = field(default_factory=tuple)
    # The high-water mark of the source's event log.
    new_watermark: datetime | None = None
    # Is this pull a COMPLETE-ENOUGH observation of current state for a snapshot provider's refresh
    # to PRUNE against it (#1109 review)?
    prunable: bool = True

    @classmethod
    def empty(
        cls, tier: LineageTier = LineageTier.NONE, *, degraded_reason: str | None = None
    ) -> WarehouseLineageResult:
        """A pull that ran and found no edges — a true observation the refresh may
        prune on, unlike :class:`WarehouseLineageUnavailableError` (which it must not).
        """
        return cls(edges=(), tier=tier, degraded_reason=degraded_reason)


class WarehouseLineageUnavailableError(RuntimeError):
    """The warehouse could not be consulted at all (connect failure, missing grant on every tier,
    unreadable response). The refresh must leave the cache untouched — wiping edges on an outage
    is the failure mode this signal prevents (mirrors
    `lineage.provider.LineageUnavailableError`).
    """


@runtime_checkable
class WarehouseLineageProvider(Protocol):
    """Provider-agnostic warehouse lineage pull — one SQL round of tiers per connection."""

    source: str
    is_incremental: bool

    def enumerate_tables(
        self,
        conn: object,
        *,
        connection_config: dict[str, object],
        limit: int | None = None,
    ) -> tuple[AssetIdentity, ...]:
        """Enumerate the tables this connection can see, as OpenLineage identities (ADR 0040 — the
        table-enumeration seam). Reads the engine's own catalog views in the engine's own case —
        the #823-safe path, so an enumerated table joins `assets` byte-for-byte with what a
        suite target or lineage edge produces.
        """
        ...

    def fetch_edges(
        self,
        conn: object,
        *,
        connection_config: dict[str, object],
        since: datetime | None = None,
    ) -> WarehouseLineageResult:
        """Pull lineage edges over an already-open SQLAlchemy ``conn`` (the caller owns its
        lifecycle, via `profile_service._open_connection`).
        """
        ...


def get_warehouse_lineage_provider(connection_type: str) -> WarehouseLineageProvider | None:
    """The warehouse-native `WarehouseLineageProvider` for a datasource type, or ``None``
    for a type with no warehouse-native lineage (flat-file/Iceberg — those get lineage
    from dbt/OpenLineage, not a warehouse system view). Lazy-imports the impls so this
    module stays free of the SQLAlchemy-heavy provider modules until a caller needs one.
    """
    if connection_type == "snowflake":
        from backend.app.lineage.warehouse_snowflake import SnowflakeLineageProvider

        return SnowflakeLineageProvider()
    if connection_type == "unity_catalog":
        from backend.app.lineage.warehouse_unity_catalog import UnityCatalogLineageProvider

        return UnityCatalogLineageProvider()
    return None


WAREHOUSE_LINEAGE_CONNECTION_TYPES: tuple[str, ...] = ("snowflake", "unity_catalog")


@cache
def snapshot_lineage_connection_types() -> tuple[str, ...]:
    """Connection types whose warehouse provider is a SNAPSHOT source — the only ones a
    stale-edge prune, and therefore a prune suspension, can apply to (#1236). Derived
    from the providers rather than restated, so a new snapshot source joins by existing.
    """
    types = []
    for connection_type in WAREHOUSE_LINEAGE_CONNECTION_TYPES:
        provider = get_warehouse_lineage_provider(connection_type)
        if provider is not None and not provider.is_incremental:
            types.append(connection_type)
    return tuple(types)


def dedupe_edges(edges: Sequence[LineageEdgePair]) -> tuple[LineageEdgePair, ...]:
    """Collapse duplicate ``(upstream, downstream)`` pairs, preserving first-seen order."""
    seen: set[tuple[tuple[str, str], tuple[str, str]]] = set()
    out: list[LineageEdgePair] = []
    for edge in edges:
        up = (edge.upstream.namespace, edge.upstream.name)
        down = (edge.downstream.namespace, edge.downstream.name)
        if up == down:
            continue  # self-edge — not lineage
        key = (up, down)
        if key in seen:
            continue
        seen.add(key)
        out.append(edge)
    return tuple(out)
"""Cache dbt-manifest lineage into `lineage_edges`, and walk it (ADR 0034, #759)."""

from __future__ import annotations

import uuid
from collections import Counter
from dataclasses import dataclass
from datetime import datetime
from typing import Any

from sqlalchemy import delete, func, select
from sqlalchemy.dialects.postgresql import insert as pg_insert
from sqlalchemy.orm import Session

from backend.app.core.logging import get_logger
from backend.app.db.models import Asset, Connection, LineageEdge
from backend.app.lineage.dbt_manifest import ManifestGraph, NodeIdentity
from backend.app.services.asset_identity import format_snowflake_name, format_unity_catalog_name
from backend.app.services.asset_service import upsert_assets

log = get_logger(__name__)

# dbt adapters whose identifiers fold like Unity Catalog (lower-case unquoted).
_UC_ADAPTERS = frozenset({"databricks", "spark"})

# Warn when fewer than this fraction of manifest nodes matched an existing asset —
# a low match rate signals a probable mis-anchor (wrong namespace borrowed).
_LOW_ANCHOR_MATCH_RATIO = 0.30

# Multi-row INSERT chunk size for the edge upserts (mirrors the asset batch).
_EDGE_CHUNK = 500


def refresh_dbt_edges(
    session: Session, *, connection: Connection, graph: ManifestGraph
) -> int | None:
    """Refresh the dbt `lineage_edges` cache from ``graph``; return the live count."""
    try:
        return _refresh_dbt_edges(session, connection=connection, graph=graph)
    except Exception as exc:  # fail-open: lineage must never break the run path
        log.warning(
            "dbt_lineage_refresh_failed",
            connection_id=str(connection.id),
            error=str(exc),
        )
        session.rollback()
        return None


def _refresh_dbt_edges(
    session: Session, *, connection: Connection, graph: ManifestGraph
) -> int | None:
    # One pass over the graph nodes → the canonical OL name per uid + the distinct
    # name set (the anchor lookup keys + the asset rows to materialize).
    canonical: dict[str, str] = {}
    names: set[str] = set()
    for uid, ident in graph.nodes.items():
        name = _canonical_name(graph.adapter_type, ident)
        if name:
            canonical[uid] = name
            names.add(name)
    if not names:
        log.warning("dbt_lineage_empty_graph", connection_id=str(connection.id))
        return None

    namespace = _resolve_namespace(session, connection=connection, names=sorted(names))
    if namespace is None:
        log.warning(
            "dbt_lineage_no_namespace_anchor",
            connection_id=str(connection.id),
            fix_hint="create a suite on one of the dbt project's tables to seed an asset "
            "namespace, or set `lineage_namespace` on the dbt connection config",
        )
        return None

    # `clock_timestamp()` (wall clock, advances *within* a transaction) — NOT `now()` (==
    # transaction start, constant for the whole tx).
    refresh_started_at = session.execute(select(func.clock_timestamp())).scalar_one()

    # Batch-materialize every node as an asset under the anchor namespace, preserving any
    # datasource-resolved provenance (env / connection_id) already on the row.
    asset_rows = [
        {
            "namespace": namespace,
            "name": name,
            "env": connection.env,
            "connection_id": connection.id,
        }
        for name in sorted(names)
    ]
    id_by_name = upsert_assets(session, asset_rows, preserve_provenance=True)
    asset_ids = {uid: id_by_name[(namespace, name)] for uid, name in canonical.items()}

    edge_rows = _edge_rows(graph, asset_ids, connection_id=connection.id)
    _upsert_edges(session, edge_rows)
    _prune_stale(session, connection_id=connection.id, refresh_started_at=refresh_started_at)
    live = session.execute(
        select(func.count())
        .select_from(LineageEdge)
        .where(LineageEdge.source == "dbt", LineageEdge.connection_id == connection.id)
    ).scalar_one()
    session.commit()
    log.info(
        "dbt_lineage_refreshed",
        connection_id=str(connection.id),
        namespace=namespace,
        nodes=len(asset_ids),
        edges=int(live),
    )
    return int(live)


def _canonical_name(adapter_type: str, ident: NodeIdentity) -> str:
    """Canonicalize a node identity to its OpenLineage ``name`` string."""
    if adapter_type == "snowflake":
        return format_snowflake_name(ident.database, ident.schema, ident.name)
    if adapter_type in _UC_ADAPTERS:
        return format_unity_catalog_name(ident.database, ident.schema, ident.name)
    return ".".join(part for part in (ident.database, ident.schema, ident.name) if part)


def _resolve_namespace(session: Session, *, connection: Connection, names: list[str]) -> str | None:
    """The OL namespace to file this manifest's assets under."""
    pinned = connection.config.get("lineage_namespace")
    if isinstance(pinned, str) and pinned.strip():
        return pinned.strip()
    return _anchor_namespace(session, names=names, env=connection.env)


def _anchor_namespace(session: Session, *, names: list[str], env: str | None) -> str | None:
    """The OL namespace to file this manifest's assets under, inferred from assets."""
    rows = session.execute(
        select(Asset.namespace, Asset.env, Asset.name, Asset.last_seen).where(Asset.name.in_(names))
    ).all()
    pool = [r for r in rows if r.env == env or r.env is None]
    if not pool:
        return None
    matched = len({r.name for r in pool})
    if matched < len(names) * _LOW_ANCHOR_MATCH_RATIO:
        log.warning("dbt_lineage_low_anchor_match", matched=matched, total=len(names), env=env)
    counts: Counter[str] = Counter(str(r.namespace) for r in pool)
    top_count = max(counts.values())
    top = sorted(ns for ns, c in counts.items() if c == top_count)
    if len(top) == 1:
        return top[0]
    log.warning("dbt_lineage_namespace_anchor_tie", namespaces=top)
    # Deterministic tie-break: latest last_seen per namespace, then lexicographic.
    latest_by_ns = {ns: max(r.last_seen for r in pool if str(r.namespace) == ns) for ns in top}
    best_ts = max(latest_by_ns.values())
    return sorted(ns for ns, ts in latest_by_ns.items() if ts == best_ts)[0]


def _edge_rows(
    graph: ManifestGraph, asset_ids: dict[str, uuid.UUID], *, connection_id: uuid.UUID
) -> list[dict[str, Any]]:
    """De-duplicated `lineage_edges` insert rows for the graph's resolvable edges."""
    seen: set[tuple[uuid.UUID, uuid.UUID]] = set()
    rows: list[dict[str, Any]] = []
    for parent_uid, child_uid in graph.edges:
        upstream = asset_ids.get(parent_uid)
        downstream = asset_ids.get(child_uid)
        if upstream is None or downstream is None or (upstream, downstream) in seen:
            continue
        seen.add((upstream, downstream))
        rows.append(
            {
                "upstream_asset_id": upstream,
                "downstream_asset_id": downstream,
                "source": "dbt",
                "connection_id": connection_id,
                "last_seen": func.clock_timestamp(),
            }
        )
    return rows


def _upsert_edges(
    session: Session, edge_rows: list[dict[str, Any]], *, chunk_size: int = _EDGE_CHUNK
) -> None:
    """Chunked multi-row edge upsert (bump `last_seen` on an already-seen edge)."""
    for start in range(0, len(edge_rows), chunk_size):
        chunk = edge_rows[start : start + chunk_size]
        stmt = pg_insert(LineageEdge).values(chunk)
        session.execute(
            stmt.on_conflict_do_update(
                constraint="uq_lineage_edges_up_down_source_conn",
                set_={"last_seen": func.clock_timestamp()},
            )
        )


def _prune_stale(
    session: Session, *, connection_id: uuid.UUID, refresh_started_at: datetime
) -> None:
    """Delete this connection's dbt edges not re-seen in the latest refresh."""
    session.execute(
        delete(LineageEdge).where(
            LineageEdge.source == "dbt",
            LineageEdge.connection_id == connection_id,
            LineageEdge.last_seen < refresh_started_at,
        )
    )


def downstream_assets(session: Session, asset_id: uuid.UUID, *, max_depth: int = 10) -> list[Asset]:
    """Distinct downstream assets of ``asset_id`` in BFS order (blast radius)."""
    return [asset for asset, _depth in _walk(session, asset_id, "down", max_depth)]


def upstream_assets(session: Session, asset_id: uuid.UUID, *, max_depth: int = 10) -> list[Asset]:
    """Distinct upstream assets of ``asset_id`` in BFS order (provenance)."""
    return [asset for asset, _depth in _walk(session, asset_id, "up", max_depth)]


@dataclass(frozen=True)
class LineageNeighbourhood:
    """The lineage subgraph around one asset — enough to *draw* it (#805)."""

    upstream: list[tuple[Asset, int]]
    downstream: list[tuple[Asset, int]]
    edges: list[tuple[uuid.UUID, uuid.UUID]]


def lineage_neighbourhood(
    session: Session, asset_id: uuid.UUID, *, max_depth: int = 10
) -> LineageNeighbourhood:
    """Both walks from ``asset_id``, with hop depth per node + the traversed edges."""
    up, up_edges = _walk_graph(session, asset_id, "up", max_depth)
    down, down_edges = _walk_graph(session, asset_id, "down", max_depth)

    ids = [aid for aid, _ in up] + [aid for aid, _ in down]
    by_id = (
        {a.id: a for a in session.scalars(select(Asset).where(Asset.id.in_(ids)))} if ids else {}
    )
    return LineageNeighbourhood(
        upstream=[(by_id[aid], d) for aid, d in up if aid in by_id],
        downstream=[(by_id[aid], d) for aid, d in down if aid in by_id],
        edges=sorted(set(up_edges) | set(down_edges)),
    )


def _walk(
    session: Session, start: uuid.UUID, direction: str, max_depth: int
) -> list[tuple[Asset, int]]:
    """`_walk_graph`, resolved to `Asset` rows (dropping the edges)."""
    order, _edges = _walk_graph(session, start, direction, max_depth)
    if not order:
        return []
    ids = [aid for aid, _ in order]
    by_id = {a.id: a for a in session.scalars(select(Asset).where(Asset.id.in_(ids)))}
    return [(by_id[aid], depth) for aid, depth in order if aid in by_id]


def _walk_graph(
    session: Session, start: uuid.UUID, direction: str, max_depth: int
) -> tuple[list[tuple[uuid.UUID, int]], set[tuple[uuid.UUID, uuid.UUID]]]:
    """Depth-capped BFS over `lineage_edges` in ``direction`` from ``start``."""
    if direction == "down":
        from_col, to_col = LineageEdge.upstream_asset_id, LineageEdge.downstream_asset_id
    else:
        from_col, to_col = LineageEdge.downstream_asset_id, LineageEdge.upstream_asset_id

    visited = {start}
    frontier = [start]
    order: list[tuple[uuid.UUID, int]] = []
    edges: set[tuple[uuid.UUID, uuid.UUID]] = set()
    depth = 0
    while frontier and depth < max_depth:
        rows = session.execute(select(from_col, to_col).where(from_col.in_(frontier))).all()
        next_frontier: list[uuid.UUID] = []
        for src, dst in rows:
            # `src`/`dst` are in walk order; store the edge in its true direction.
            edges.add((src, dst) if direction == "down" else (dst, src))
            if dst not in visited:
                visited.add(dst)
                order.append((dst, depth + 1))
                next_frontier.append(dst)
        frontier = next_frontier
        depth += 1
    return order, edges

def summarize_asset(session: Session, asset: Asset) -> AssetSummary:
    """Roll one already-loaded asset up into its list-row summary — workspace-true
    (ADR 0037), so it takes no user. An asset with zero suites rolls up to an
    empty (no-run) health summary. Used by the admin PATCH response, where the
    asset need not have suites to have metadata.
    """
    suites = list(session.scalars(select(Suite).where(Suite.asset_id == asset.id)))
    outcome_by_suite = _latest_outcomes(session, suites)
    return _roll_up(asset, [outcome_by_suite[s.id] for s in suites])


def _monitored_ids(session: Session, ids: list[uuid.UUID]) -> set[uuid.UUID]:
    """Which of ``ids`` have ≥1 suite targeting them (globally — a structural fact,
    not a grant). One grouped query for the whole neighbourhood (no N+1).
    """
    if not ids:
        return set()
    return {
        asset_id
        for (asset_id,) in session.execute(
            select(Suite.asset_id).where(Suite.asset_id.in_(ids)).group_by(Suite.asset_id)
        )
    }


@dataclass(frozen=True)
class AssetCoverage:
    """How many of a connection's known assets any suite targets (#1701)."""

    total: int
    unmonitored: int


def coverage_by_connection(
    session: Session, connection_ids: list[uuid.UUID]
) -> dict[uuid.UUID, AssetCoverage]:
    """Per connection: assets DataQ knows of, and how many no suite targets.

    Counted over the whole workspace, not the caller's grants — the same
    workspace-true rollup ADR 0037 defines for assets. Connections with no known
    assets are absent from the mapping rather than present with a zero.
    """
    if not connection_ids:
        return {}
    rows = session.execute(
        select(Asset.connection_id, Asset.id).where(Asset.connection_id.in_(connection_ids))
    ).all()
    if not rows:
        return {}
    monitored = _monitored_ids(session, [asset_id for _, asset_id in rows])
    totals: dict[uuid.UUID, list[int]] = defaultdict(lambda: [0, 0])
    for connection_id, asset_id in rows:
        entry = totals[connection_id]
        entry[0] += 1
        if asset_id not in monitored:
            entry[1] += 1
    return {cid: AssetCoverage(total=t, unmonitored=u) for cid, (t, u) in totals.items()}


def _lineage_edge_refs(
    session: Session,
    edges: list[tuple[uuid.UUID, uuid.UUID]],
) -> list[LineageEdgeRef]:
    """The neighbourhood's edges with their column-level refinement (#901), shown
    in full to every member (ADR 0037 — column names are schema metadata, i.e.
    identity). Column data is unioned across the sources that observed the edge
    (two provenance rows for one asset pair are one drawn edge).
    """
    if not edges:
        return []
    pairs: dict[tuple[uuid.UUID, uuid.UUID], set[tuple[str, str]]] = {}
    for up, down, cols in session.execute(
        select(
            LineageEdge.upstream_asset_id,
            LineageEdge.downstream_asset_id,
            LineageEdge.columns,
        ).where(
            tuple_(LineageEdge.upstream_asset_id, LineageEdge.downstream_asset_id).in_(edges),
            LineageEdge.columns.is_not(None),
            # Exclude JSON 'null' in SQL (#907) — rows bulk-written before
            # `none_as_null` carry it and pass `is_not(None)`.
            func.jsonb_typeof(LineageEdge.columns) != "null",
        )
    ):
        # Defensive shape check: `columns` is app-written JSONB, but a malformed value must degrade
        # to "skipped", never 500 the asset page.
        if not isinstance(cols, (list, tuple)):
            log.warning(
                "lineage_edge_columns_malformed",
                upstream_asset_id=str(up),
                downstream_asset_id=str(down),
                value_type=type(cols).__name__,
            )
            continue
        valid = [
            (str(entry[0]), str(entry[1]))
            for entry in cols
            if isinstance(entry, (list, tuple)) and len(entry) == 2
        ]
        # The loud-degradation contract covers ENTRIES too (#924 review): a wrong-arity/non-list
        # item inside a well-formed list must not vanish silently.
        if len(valid) != len(cols):
            log.warning(
                "lineage_edge_column_entries_malformed",
                upstream_asset_id=str(up),
                downstream_asset_id=str(down),
                dropped=len(cols) - len(valid),
            )
        pairs.setdefault((up, down), set()).update(valid)
    return [
        LineageEdgeRef(
            source=up,
            target=down,
            columns=tuple(sorted(cols)) if (cols := pairs.get((up, down))) else None,
        )
        for up, down in edges
    ]


def _lineage_nodes(
    assets: list[tuple[Asset, int]],
    monitored: set[uuid.UUID],
) -> list[LineageNode]:
    """Map reachable lineage assets (+ their hop depth) to render-only nodes —
    fully named for every member (ADR 0037); ``is_monitored`` is the true
    structural fact.
    """
    return [
        LineageNode(
            id=a.id,
            namespace=a.namespace,
            name=a.name,
            env=a.env,
            is_monitored=a.id in monitored,
            depth=depth,
        )
        for a, depth in assets
    ]


def update_asset_metadata(
    session: Session,
    asset_id: uuid.UUID,
    *,
    owner_user_id: uuid.UUID | None = None,
    description: str | None = None,
    set_owner: bool = False,
    set_description: bool = False,
